import assert from 'node:assert/strict';
import { readFile, writeFile } from 'node:fs/promises';
import { pathToFileURL } from 'node:url';
import { fork } from 'node:child_process';
import { createServer } from 'node:http';
import { once } from 'node:events';
import { getHeapStatistics } from 'node:v8';

if (process.argv[2] === 'receiver') {
  const server = createServer((request, response) => {
    request.resume();
    request.on('end', () => response.writeHead(202, {'content-type':'application/json'}).end('{}'));
  });
  server.listen(0,'127.0.0.1');
  await once(server,'listening');
  process.send(server.address().port);
  process.on('message',()=>server.close(()=>process.exit()));
} else {
  const root='/Users/ftatilon/Dev/GitHub/chunkify-player/tests/collector/docker/';
  const receiver=fork(new URL(import.meta.url),['receiver'],{stdio:['ignore','ignore','inherit','ipc']});
  const [port]=await once(receiver,'message');
  const samples=[];
  globalThis.__generatorProbe={
    async containerCollector(){return {url:`http://127.0.0.1:${port}`,name:'memory-probe',volume:'none',keys:{ingest_key:'fixture'},
      lastLogs:'',async get(){return {};},async start(){},async stop(){return {OOMKilled:false,ExitCode:0};},async close(){}};},
    async docker(args){
      if(args[0]!=='exec')return '0 /data';
      const memory={at:Date.now(),...process.memoryUsage()};samples.push(memory);
      return '0\nusage_usec 0\nVmRSS: 0 kB\n0 /data\n/dev/test 999999999 0 999999999 0% /data';
    },
    async verify(server,sent,acknowledged,preloadIds){return {summary:{},persisted_new:acknowledged.size-preloadIds.size,persisted_without_ack:0,verification:{}};},
  };
  let source=await readFile(root+'benchmark.mjs','utf8');
  source=source.replace('import { containerCollector, docker, image } from "./support.mjs";',
    'const {containerCollector,docker,verify}=globalThis.__generatorProbe; const image="probe";');
  source=source.replace('export async function verify(', 'async function unusedVerify(');
  source=source.replaceAll('from "./workload.mjs"',`from "${pathToFileURL(root+'workload.mjs')}"`);
  process.env.COLLECTOR_LOAD_MAX_EVENTS='1000000';
  try {
    const {captureWorkload,measure}=await import('data:text/javascript;base64,'+Buffer.from(source).toString('base64'));
    const workload=await captureWorkload({browserContext:true});
    const r=await measure({name:'generator-memory-probe',format:'native',rate:Number(process.env.PROBE_RATE ?? 10000),seconds:Number(process.env.PROBE_SECONDS ?? 50),concurrency:4096,queries:false},workload);
    const result={description:'Actual benchmark sender and ledgers, isolated from Docker and database. Separate HTTP receiver drains bodies and returns202. Persistence verification stubbed; this is not a collector capacity result.',
      heap_limit:getHeapStatistics().heap_size_limit,requests:r.requests,elapsed_seconds:r.elapsed_seconds,abort_reason:r.abort_reason,samples,peak_rss:Math.max(...samples.map(s=>s.rss)),resources:r.resources};
    await writeFile(process.env.PROBE_REPORT ?? '/tmp/chunkify-generator-memory-baseline.json',JSON.stringify(result,null,2));
    console.log(JSON.stringify({...result,samples:undefined,resources:undefined}));
    assert.ok(r.abort_reason === null || (process.env.PROBE_FULL === '1' && r.abort_reason === 'unique event safety limit'), 'generator must complete without exceeding its 1GiB memory guard');
    if(process.env.PROBE_FULL === '1')assert.equal(r.records.newly_acknowledged,1000000);
  } finally {
    receiver.kill('SIGTERM');
  }
}

cancellation_script:
import assert from 'node:assert/strict';
import { spawn } from 'node:child_process';
import { readFile, writeFile } from 'node:fs/promises';
const report='/tmp/chunkify-generator-cancel-smoke-20261019.json';
const child=spawn(process.execPath,['tests/collector/docker/load.mjs'],{env:{...process.env,
 DOCKER_CONFIG:'/tmp/chunkify-collector-docker-config',DOCKER_HOST:'unix:///Users/ftatilon/.docker/run/docker.sock',
 COLLECTOR_IMAGE:'chunkify-analytics-collector:separate-reader-prototype',COLLECTOR_LOAD_CASES:'native-100',
 COLLECTOR_LOAD_SECONDS:'60',COLLECTOR_LOAD_DURABLE_QUEUE:'1',COLLECTOR_LOAD_READ_WORKER:'1',COLLECTOR_LOAD_BROWSER_CONTEXT:'1',
 COLLECTOR_LOAD_REPORT:report},stdio:['ignore','ignore','pipe']});
let timer;let signaled=false;
child.stderr.on('data',data=>{process.stderr.write(data);if(!timer && data.toString().includes('Measuring'))timer=setTimeout(()=>{signaled=true;child.kill('SIGTERM');},10000);});
const timeout=setTimeout(()=>child.kill('SIGTERM'),90000);
try {
 const code=await new Promise((resolve,reject)=>{child.once('exit',resolve);child.once('error',reject);});
 assert.ok(signaled);
 assert.equal(code,130);
 const r=JSON.parse(await readFile(report));
 assert.equal(r.status,'interrupted');
 assert.equal(r.results.length,1);
 const result=r.results[0];
 assert.ok(result.verification.acknowledged_events>0);
 assert.equal(result.records.persisted_new,result.records.newly_acknowledged);
 assert.ok(result.verification.payloads && result.verification.otlp_context && result.verification.summary && result.verification.per_video);
 r.launcher_cancellation={signal:'SIGTERM',exit_code:code,verified_after_interrupt:true};
 await writeFile(report,JSON.stringify(r,null,2)+'\n');
 console.log(JSON.stringify({exit_code:code,status:r.status,acknowledged_and_verified:result.verification.acknowledged_events,heap_limit_mib:r.generator_runtime.v8_heap_limit_bytes/1048576}));
} finally {clearTimeout(timer);clearTimeout(timeout);}
